for key, fix in pairs(FIX) do
	local e = Entry(key)
	if e then
		for _, a in ipairs(fix.add or {}) do
			if not Boss(e, a.npc) then
				local pos = 1
				if a.after then local _, i = Boss(e, a.after); pos = (i or #e.bosses) + 1 end
				local loot = {}
				for _, id in ipairs(a.loot) do loot[#loot + 1] = id; loot[#loot + 1] = -1 end
				table.insert(e.bosses, pos, { name = a.name, npc = a.npc, level = a.level, hp = a.hp, loot = loot })
				for i = #(e.trash or {}), 1, -1 do if e.trash[i].npc == a.npc then table.remove(e.trash, i) end end
			end
		end
		for npc, items in pairs(fix.loot or {}) do
			local b = Boss(e, npc)
			if b then AddLoot(b, items) end
		end
		if fix.trash then
			local t
			for _, b in ipairs(e.bosses) do if b.type == "extra" and (b.name == "Trash" or b.name == "Trash Mobs") then t = b end end
			if not t then
				t = { name = "Trash", type = "extra", loot = {} }
				table.insert(e.bosses, t)
			end
			AddLoot(t, fix.trash)
		end
	end
end

