ns.DungeonQuestInfo[7509] = { "The Forging of Quel'Serrar", 60, 60, 0, 0, 3, 7508, giver = { "Lorekeeper Lydros", nil, nil, nil, 1 }, turnin = { "Lorekeeper Lydros", nil, nil, nil, 1 }, objectives = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence. The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse. Do this and Quel'Serrar will be yours.", items = { 18492, 1 }, reward = { 18348, 1 } }
ns.DungeonQuestInfo[7581] = { "The Prison's Bindings", 60, 60, 0, 0, 256, 0, giver = { "Daio the Decrepit", 0, -11686, -2385, 0 }, turnin = { "Daio the Decrepit", 0, -11686, -2385, 0 }, objectives = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.", items = { 18603, 1 } }
ns.DungeonQuestInfo[7644] = { "Blessed Arcanite Barding", 60, 60, 1, 5, 2, 7643, giver = { "Ancient Equine Spirit", 0, -8578, 881, 1 }, turnin = { "Lord Grayson Shadowbreaker", 0, -8578, 881, 0 }, objectives = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." }
